import{t as e}from"./api-7M9YWvHU.js";var t={async createCheckout(t){return(await e.post(`/donations/checkout`,t)).data},async getDonationStatus(t){return(await e.get(`/donations/${t}/status`)).data},async getDmsDashboard(){return(await e.get(`/donations/admin/dashboard`)).data},async getDmsDonations(t){return(await e.get(`/donations/admin/donations`,{params:t})).data},async getDmsDonationDetail(t){return(await e.get(`/donations/admin/donations/${t}`)).data},async refundDonation(t,n){return(await e.post(`/donations/admin/donations/${t}/refund`,{reason:n})).data},async getDmsDonors(t){return(await e.get(`/donations/admin/donors`,{params:t})).data},async getDmsReports(t){return(await e.get(`/donations/admin/reports`,{params:{year:t}})).data},async reconcileDms(){return(await e.post(`/donations/admin/reconcile`)).data},getExportCsvUrl(){return`${e.defaults.baseURL||`/api/v1`}/donations/admin/export`}};export{t};